1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // project references client via FK; H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the duration of the clear, then restore it.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE dashboard_config");
39	        jdbc.execute("TRUNCATE TABLE note RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE project_tag RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE tag RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE task RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE payment RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE line_item RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE invoice RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE contact RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
49	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
50	    }
51	
52	    /**
53	     * Parse a seeded timestamp, tolerating both a full ISO-8601 instant ({@code 2026-02-01T09:00:00Z})
54	     * and a bare date ({@code 2026-02-01}, taken at the start of the day in UTC).
55	     */
56	    private static java.time.Instant parseInstant(String value) {
57	        if (value.length() == 10) {
58	            return java.time.LocalDate.parse(value).atStartOfDay(java.time.ZoneOffset.UTC).toInstant();
59	        }
60	        return java.time.Instant.parse(value);
61	    }
62	
63	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
64	    @PostMapping("/seed")
65	    @SuppressWarnings("unchecked")
66	    public void seed(@RequestBody Map<String, Object> fixture) {
67	        Object asOf = fixture.get("asOf");
68	        if (asOf != null) {
69	            // The dashboard's reference date for deciding which SENT invoices are overdue (V24).
70	            jdbc.update("INSERT INTO dashboard_config (id, as_of) VALUES (1, ?)",
71	                    java.sql.Date.valueOf(asOf.toString()));
72	        }
73	        List<Map<String, Object>> clients =
74	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
75	        for (Map<String, Object> client : clients) {
76	            jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
77	                    ((Number) client.get("id")).longValue(), client.get("name"), client.get("email"));
78	        }
79	        List<Map<String, Object>> projects =
80	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
81	        for (Map<String, Object> project : projects) {
82	            Object status = project.getOrDefault("status", "ACTIVE");
83	            boolean archived = Boolean.TRUE.equals(project.getOrDefault("archived", Boolean.FALSE));
84	            Object budgetValue = project.get("budget");
85	            java.math.BigDecimal budget = budgetValue == null ? java.math.BigDecimal.ZERO
86	                    : new java.math.BigDecimal(budgetValue.toString());
87	            long projectId = ((Number) project.get("id")).longValue();
88	            // project.code carries a UNIQUE constraint (V33). A fixture that omits the code can seed
89	            // several projects, so synthesise a per-project code when none is supplied rather than
90	            // letting them all collide on the empty-string default; honour an explicit code as given.
91	            Object code = project.get("code");
92	            String codeValue = project.containsKey("code")
93	                    ? (code == null ? "" : code.toString())
94	                    : "seed-project-" + projectId;
95	            jdbc.update(
96	                    "INSERT INTO project (id, name, client_id, status, archived, budget, code) "
97	                            + "VALUES (?, ?, ?, ?, ?, ?, ?)",
98	                    projectId, project.get("name"),
99	                    ((Number) project.get("clientId")).longValue(), status, archived, budget,
100	                    codeValue);
101	        }
102	        List<Map<String, Object>> tasks =
103	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
104	        for (Map<String, Object> task : tasks) {
105	            Object done = task.getOrDefault("done", Boolean.FALSE);
106	            jdbc.update("INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
107	                    ((Number) task.get("id")).longValue(),
108	                    ((Number) task.get("projectId")).longValue(), task.get("title"),
109	                    Boolean.TRUE.equals(done));
110	        }
111	        List<Map<String, Object>> notes =
112	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
113	        long maxNoteId = 0;
114	        for (Map<String, Object> note : notes) {
115	            long noteId = ((Number) note.get("id")).longValue();
116	            maxNoteId = Math.max(maxNoteId, noteId);
117	            jdbc.update(
118	                    "INSERT INTO note (id, target_type, target_id, body, at) VALUES (?, ?, ?, ?, ?)",
119	                    noteId, note.get("targetType"),
120	                    ((Number) note.get("targetId")).longValue(), note.get("text"),
121	                    java.sql.Timestamp.from(parseInstant(note.get("at").toString())));
122	        }
123	        if (maxNoteId > 0) {
124	            // Seeding explicit ids does not advance H2's IDENTITY sequence, so a note created later
125	            // through the API would collide on id=1. Nudge the sequence past the seeded ids.
126	            jdbc.execute("ALTER TABLE note ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
127	        }
128	        List<Map<String, Object>> tags =
129	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
130	        for (Map<String, Object> tag : tags) {
131	            jdbc.update("INSERT INTO tag (id, name) VALUES (?, ?)",
132	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
133	        }
134	        List<Map<String, Object>> projectTags =
135	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
136	        for (Map<String, Object> projectTag : projectTags) {
137	            jdbc.update("INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
138	                    ((Number) projectTag.get("projectId")).longValue(),
139	                    ((Number) projectTag.get("tagId")).longValue());
140	        }
141	        List<Map<String, Object>> contacts =
142	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
143	        for (Map<String, Object> contact : contacts) {
144	            boolean primary = Boolean.TRUE.equals(contact.getOrDefault("primary", Boolean.FALSE));
145	            jdbc.update(
146	                    "INSERT INTO contact (id, client_id, name, email, role, is_primary) "
147	                            + "VALUES (?, ?, ?, ?, ?, ?)",
148	                    ((Number) contact.get("id")).longValue(),
149	                    ((Number) contact.get("clientId")).longValue(), contact.get("name"),
150	                    contact.get("email"), contact.get("role"), primary);
151	        }
152	        List<Map<String, Object>> invoices =
153	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
154	        for (Map<String, Object> invoice : invoices) {
155	            Object status = invoice.getOrDefault("status", "DRAFT");
156	            Object issuedDate = invoice.get("issuedDate");
157	            Object dueDate = invoice.get("dueDate");
158	            long invoiceId = ((Number) invoice.get("id")).longValue();
159	            // An invoice's amount is the sum of its line items (quantity times unit price); work it
160	            // out here so a fixture lists the things being charged for, not a pre-computed figure.
161	            // A fixture may still pass an explicit amount for an invoice with no line items.
162	            List<Map<String, Object>> lineItems =
163	                    (List<Map<String, Object>>) invoice.getOrDefault("lineItems", null);
164	            java.math.BigDecimal amount;
165	            if (lineItems != null) {
166	                amount = java.math.BigDecimal.ZERO;
167	                for (Map<String, Object> lineItem : lineItems) {
168	                    java.math.BigDecimal unitPrice =
169	                            new java.math.BigDecimal(lineItem.get("unitPrice").toString());
170	                    int qty = ((Number) lineItem.get("qty")).intValue();
171	                    amount = amount.add(unitPrice.multiply(java.math.BigDecimal.valueOf(qty)));
172	                }
173	            } else {
174	                lineItems = List.of();
175	                Object explicit = invoice.get("amount");
176	                amount = explicit == null ? java.math.BigDecimal.ZERO
177	                        : new java.math.BigDecimal(explicit.toString());
178	            }
179	            Object discountPct = invoice.getOrDefault("discountPct", 0);
180	            Object taxPct = invoice.getOrDefault("taxPct", 0);
181	            jdbc.update(
182	                    "INSERT INTO invoice "
183	                            + "(id, project_id, amount, status, issued_date, due_date, discount_pct, "
184	                            + "tax_pct) "
185	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
186	                    invoiceId, ((Number) invoice.get("projectId")).longValue(), amount, status,
187	                    issuedDate == null ? null : java.sql.Date.valueOf(issuedDate.toString()),
188	                    dueDate == null ? null : java.sql.Date.valueOf(dueDate.toString()),
189	                    ((Number) discountPct).intValue(), ((Number) taxPct).intValue());
